cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
# Benchmark site - serves static files on port 8080 with rate limiting
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    root /var/www/html;
    index index.html;

    # Detailed request logging (format defined in nginx.conf)
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log  /var/log/nginx/benchmark-error.log warn;

    # Rate limiting: 10 req/s per IP, burst of 10 (zone defined in nginx.conf)
    limit_req zone=benchmark_limit burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    # Custom 404 error page
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF

mkdir -p /var/www/html
printf 'Welcome to the benchmark webserver\n' > /var/www/html/index.html
printf 'Page not found - Please check your URL\n' > /var/www/html/404.html
chmod 755 /var/www/html /var/www/html/index.html /var/www/html/404.html
chown -R www-data:www-data /var/www/html
rm -f /etc/nginx/sites-enabled/default
touch /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log
chown www-data:adm /var/log/nginx/benchmark-access.log /var/log/nginx/benchmark-error.log
ls -la /etc/nginx/sites-enabled /etc/nginx/conf.d /var/www/html

python3 - <<'EOF'
p='/etc/nginx/conf.d/benchmark-site.conf'
s=open(p).read()
s=s.replace("""    # Custom 404 error page
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
""","""    # Custom 404 error page
    error_page 404 /404.html;
""")
open(p,'w').write(s)
EOF
cat /etc/nginx/conf.d/benchmark-site.conf
echo "=== TEST ==="
nginx -t

